//! 🧪️ Native paged authority and original edit fields match Node decisions and exact alias custody.
use super::*;
use crate::MutationMeta;
use semio_framework_replication_ids::ActorId;
use semio_framework_value::{retirement::RetireOwned,retained_clone::RetainedCloneSource,paged::PagedUtf8};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;

#[derive(semio_framework_value::RetireOwned)]
struct Authority{actor:PagedUtf8<{usize::MAX}>,line:Option<PagedUtf8<{usize::MAX}>>,group:Option<PagedUtf8<{usize::MAX}>>,sequence:i32,clock:HybridLogicalTimestamp}
impl ArtifactCanonicalEditAuthority for Authority{fn sequence_number(&self)->i32{self.sequence}fn clock(&self)->HybridLogicalTimestamp{self.clock}fn actor(&self)->Text<'_>{&self.actor}fn line(&self)->Option<Text<'_>>{self.line.as_ref().map(|value|value as Text<'_>)}fn group(&self)->Option<Text<'_>>{self.group.as_ref().map(|value|value as Text<'_>)}}
fn grant(demand:RetirementDemand)->RetainedCloneGrant{assert!(demand.copy_bytes+demand.capacity_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth}}
fn clock(value:&serde_json::Value)->HybridLogicalTimestamp{HybridLogicalTimestamp{actor:value["actor"].as_u64().unwrap(),physical_ms:value["physical_ms"].as_u64().unwrap(),logical:value["logical"].as_u64().unwrap()}}
fn optional(value:&serde_json::Value)->Option<String>{value.as_str().map(str::to_owned)}
fn alias_grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:semio_framework_value::retained_clone::RetainedCloneBinding::alias_copy_bytes(),maximum_depth:2,..Default::default()}}
fn source<T:RetireOwned+Sync>(value:T)->RetainedCloneSource<T>{let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<16,maximum_capacity_bytes:1<<16,maximum_release_bytes:1<<20,maximum_depth:4096};let mut admission=RetainedCloneSource::admission_owned(value,());let mut output=None;for _ in 0..64{if admission.terminal_is_empty(){break}if admission.phase()=="ready"{admission.take_output(&mut output,g).result.unwrap();}else{admission.advance(g).result.unwrap();}}output.expect("staged source admission")}
fn close<T:RetireOwned+Sync>(source:&mut RetainedCloneSource<T>){for turn in 0..100000{if source.terminal_is_empty(){return;}let work=source.next_close_copy_byte_demand().unwrap();let admitted=grant(RetirementDemand{copy_bytes:work,capacity_bytes:source.next_close_capacity_byte_demand(work).unwrap(),release_bytes:source.next_close_release_byte_demand().unwrap(),depth:source.next_close_depth_demand().unwrap()});let(step,heap)=observe(||source.close_step(admitted).result.unwrap());assert!(step.progress().fits(admitted));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(turn<99999||source.terminal_is_empty());}}

#[test]
fn canonical_native_semantic_authority_preserves_paged_originals_under_byte_grants_and_alias_cancellation(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let authored=&fixture["authority"];
 for repeat in fixture["actorRepeats"].as_array().unwrap(){let repeat=repeat.as_u64().unwrap()as usize;let actor=format!("{}{}",authored["actor"].as_str().unwrap(),fixture["actorSuffix"].as_str().unwrap().repeat(repeat));
  for row in fixture["cases"].as_array().unwrap(){let input=&row["edit"];let mut pauses:Vec<Option<usize>>=fixture["pauses"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize)).collect();pauses.push(None);
   for pause in pauses{
    let authority=Authority{actor:actor.as_str().into(),line:optional(&authored["line"]).map(Into::into),group:optional(&authored["group"]).map(Into::into),sequence:authored["sequence"].as_i64().unwrap()as i32,clock:clock(&authored["clock"])};let authority_chunk=authority.actor.chunks().next().unwrap().as_ptr();let mut authority=source(authority);
    let owned_actor=|value:&serde_json::Value|optional(value).map(|value|if value==authored["actor"].as_str().unwrap(){actor.to_owned()}else{value}).map(semio_framework_value::SharedUtf8::from);let meta=MutationMeta{author_id:owned_actor(&input["author"]).map(ActorId),timestamp:clock(&input["clock"]),group_id:optional(&input["group"]),mutation_id:None,dependencies:Vec::new(),base_version:0,undo_policy:semio_framework_replication_wire_core::UndoPolicy::ExactBaseOnly,payload_hash:None,semantic_kind:None,label:None,origin:crate::MutationOrigin::Owner,transaction:None};
    let mut edit=Box::new(Edit::<bool>{id:input["id"].as_str().unwrap().to_owned(),actor:owned_actor(&input["actor"]),line:optional(&input["line"]),sequence_number:input["sequence"].as_i64().unwrap()as i32,forwards:vec![true;input["forwardCount"].as_u64().unwrap()as usize],mutation_meta:vec![meta;input["metaCount"].as_u64().unwrap()as usize],inverse:semio_framework_value::RetainedPublicationRoot::new(semio_framework_value_persistent::list::PagedList::new()),verb:None,started_at:String::new(),finished_at:None});edit.id.reserve(8192);let pointer=edit.as_ref()as*const Edit<bool>;let id=edit.id.as_ptr();let mut edit=source(edit);
    assert_eq!(authority.borrow().get().actor.chunks().next().unwrap().as_ptr(),authority_chunk);assert_eq!(edit.borrow().get().as_ref()as*const Edit<bool>,pointer);assert_eq!(edit.borrow().get().id.as_ptr(),id);
    let(((authority_projection,_),(edit_projection,_)),heap)=observe(||(authority.project_owned(0,|owner|owner as&dyn ArtifactCanonicalEditAuthority,alias_grant()).result.unwrap(),edit.project_owned(0,|owner|owner.as_ref(),alias_grant()).result.unwrap()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
    let admitted=grant(ArtifactCanonicalEditAuthorityCursor::<bool>::constructor_demand());let((mut cursor,progress),heap)=observe(||ArtifactCanonicalEditAuthorityCursor::admit(authority_projection,edit_projection,admitted).unwrap_or_else(|_|panic!("native semantic cursor")));assert!(progress.fits(admitted));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
    let mut turns=0;while !cursor.terminal_is_empty(){assert!(turns<100000);if pause==Some(turns){cursor.begin_close();}let(demand,heap)=observe(||cursor.next_demand().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let admitted=grant(demand);let(zero,heap)=observe(||cursor.advance(RetainedCloneGrant::default()).unwrap());assert_eq!(zero.progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
     for refused in [RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..admitted},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..admitted},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..admitted},RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..admitted}]{if refused==admitted{continue;}let(step,heap)=observe(||cursor.advance(refused).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
     let(step,heap)=observe(||cursor.advance(admitted).unwrap());assert!(step.progress().fits(admitted));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));turns+=1;}
    if pause.is_none(){assert_eq!(cursor.decision(),row["accepted"].as_bool());}else if pause.unwrap()<turns{assert_eq!(cursor.decision(),None);}assert_eq!(authority.borrow().get().actor.chunks().next().unwrap().as_ptr(),authority_chunk);assert_eq!(edit.borrow().get().as_ref()as*const Edit<bool>,pointer);assert_eq!(edit.borrow().get().id.as_ptr(),id);let(_,heap)=observe(||drop(cursor));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));close(&mut edit);close(&mut authority);let(_,heap)=observe(||{drop(edit);drop(authority);});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
   }
  }
 }
}
